// Focused tests for the package generator of C-0018-deduplicated-packages (`method.md`, `upgrade.md`):
// the tracked manifest `models/architecture/package-manifest.json` records the generated bytes, so
// verification passes from a fresh checkout with no built `packages/` tree, and a stale, missing or extra
// generated entry is reported. Every root is a throwaway directory; this repository's own generation is
// never read.

import { afterAll, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { MANIFEST_PATH, diskFindings, manifestFindings, materialize, readManifest, writePackages } from "./package";

const TEMP_DIRS: string[] = [];
const TIMEOUT = 60_000;

/** A throwaway kernel root with one skill, the advisor resource and a `package.json`. */
function fixture(): string {
  const root = mkdtempSync(join(tmpdir(), "grace5-package-"));
  TEMP_DIRS.push(root);
  writeFileSync(join(root, "package.json"), `{\n  "description": "a fixture kernel",\n  "version": "1.0.0",\n  "license": "MIT"\n}\n`);
  mkdirSync(join(root, "skills", "grace5-alpha"), { recursive: true });
  writeFileSync(join(root, "skills", "grace5-alpha", "SKILL.md"), "# alpha\n");
  mkdirSync(join(root, "models", "architecture"), { recursive: true });
  writeFileSync(join(root, "models", "architecture", "advisor-guidance.md"), "guidance\n");
  mkdirSync(join(root, "models", "architecture", "extensions"));
  writeFileSync(join(root, "models", "architecture", "extensions", "orchestration.md"), "roles: [coordinator]\n");
  return root;
}

/** The `packages` object of the manifest on disk, for a deliberate edit. */
function manifestRecord(root: string): Record<string, string> {
  const parsed: unknown = JSON.parse(readFileSync(join(root, MANIFEST_PATH), "utf8"));
  if (typeof parsed !== "object" || parsed === null || !("packages" in parsed)) throw new Error("the manifest has no packages object");
  const packages = parsed.packages;
  if (typeof packages !== "object" || packages === null) throw new Error("the manifest packages is not an object");
  const record: Record<string, string> = {};
  for (const [key, value] of Object.entries(packages)) {
    if (typeof value !== "string") throw new Error(`the manifest entry is not a hash string: ${key}`);
    record[key] = value;
  }
  return record;
}

function writeManifest(root: string, record: Record<string, string>): void {
  writeFileSync(join(root, MANIFEST_PATH), `${JSON.stringify({ packages: record }, null, 2)}\n`);
}

afterAll(() => {
  for (const dir of TEMP_DIRS) rmSync(dir, { recursive: true, force: true });
});

test(
  "the generator materializes the three packages, records their bytes and verifies clean, also without a built tree",
  () => {
    const root = fixture();
    const materialization = materialize(root);
    writePackages(root, materialization);

    expect([...materialization.packages.keys()].sort()).toEqual(["claude-plugin", "openpackage", "skills"]);
    expect(materialization.files.has("skills/grace5-alpha/SKILL.md")).toBe(true);
    expect(materialization.files.has("claude-plugin/skills/grace5-alpha/SKILL.md")).toBe(true);
    expect(materialization.files.has("openpackage/advisor-guidance.md")).toBe(true);
    for (const [id, files] of materialization.packages) {
      expect(materialization.files.get(`${id}/extensions/orchestration.md`)?.toString()).toBe("roles: [coordinator]\n");
      expect([...files.keys()].some((file) => file.includes("grace5-orchestrate/"))).toBe(false);
    }

    expect(readManifest(root).size).toBe(materialization.files.size);
    expect(manifestFindings(readManifest(root), materialization)).toEqual([]);
    expect(diskFindings(root, materialization)).toEqual([]);

    // A fresh checkout has the tracked manifest and no built packages/ tree: verification still passes.
    rmSync(join(root, "packages"), { recursive: true });
    expect(manifestFindings(readManifest(root), materialization)).toEqual([]);
    expect(diskFindings(root, materialization)).toEqual([]);
  },
  TIMEOUT,
);

test(
  "a manifest entry that is stale, missing or extra is reported",
  () => {
    const root = fixture();
    const materialization = materialize(root);
    writePackages(root, materialization);
    const key = "claude-plugin/README.md";

    const changed = manifestRecord(root);
    changed[key] = "0".repeat(64);
    writeManifest(root, changed);
    expect(manifestFindings(readManifest(root), materialization)).toContain(`stale ${key}`);

    const missing = manifestRecord(root);
    delete missing[key];
    writeManifest(root, missing);
    expect(manifestFindings(readManifest(root), materialization)).toContain(`missing ${key}`);

    const extra = manifestRecord(root);
    extra["claude-plugin/ghost.md"] = "0".repeat(64);
    writeManifest(root, extra);
    expect(manifestFindings(readManifest(root), materialization)).toContain("extra claude-plugin/ghost.md");
  },
  TIMEOUT,
);

test(
  "a built file that is changed, missing or extra is reported against the generation",
  () => {
    const root = fixture();
    const materialization = materialize(root);
    writePackages(root, materialization);
    const built = join(root, "packages", "claude-plugin", "README.md");

    rmSync(built);
    expect(diskFindings(root, materialization)).toContain("missing claude-plugin/README.md");

    writeFileSync(built, "edited by hand\n");
    expect(diskFindings(root, materialization)).toContain("stale claude-plugin/README.md");

    writeFileSync(join(root, "packages", "claude-plugin", "extra.md"), "not generated\n");
    expect(diskFindings(root, materialization)).toContain("extra claude-plugin/extra.md");
  },
  TIMEOUT,
);
